using System.Globalization;using WAID.Application.Services;namespace WAID.Infrastructure.Persistence;public sealed class SqlitePerformanceHistoryRepository(WaidDatabase database):IPerformanceHistoryRepository
{private long _generation;public long Generation=>Interlocked.Read(ref _generation);public async Task SaveSamplesAsync(IReadOnlyList<PerformanceMetricSample>samples,CancellationToken token){await using var c=database.OpenConnection();await using var tx=await c.BeginTransactionAsync(token);try{foreach(var x in samples){await using var q=c.CreateCommand();q.Transaction=(Microsoft.Data.Sqlite.SqliteTransaction)tx;q.CommandText="INSERT INTO performance_samples(id,metric_kind,captured_utc,value,unit,quality,source,detail)VALUES($id,$kind,$time,$value,$unit,$quality,$source,$detail)";q.Parameters.AddWithValue("$id",x.Id.ToString());q.Parameters.AddWithValue("$kind",x.Kind.ToString());q.Parameters.AddWithValue("$time",x.CapturedAtUtc.ToUniversalTime().ToString("O"));q.Parameters.AddWithValue("$value",x.Value is null?DBNull.Value:x.Value.Value);q.Parameters.AddWithValue("$unit",x.Unit);q.Parameters.AddWithValue("$quality",(int)x.Quality);q.Parameters.AddWithValue("$source",x.Source);q.Parameters.AddWithValue("$detail",x.Detail is null?DBNull.Value:x.Detail);await q.ExecuteNonQueryAsync(token);}await tx.CommitAsync(token);Interlocked.Increment(ref _generation);}catch{await tx.RollbackAsync(CancellationToken.None);throw;}}
 public async Task ReplaceRollupsAsync(PerformanceMetricKind kind,MetricResolution resolution,DateTimeOffset fromUtc,IReadOnlyList<PerformanceMetricRollup>rollups,CancellationToken token){await using var c=database.OpenConnection();await using var tx=await c.BeginTransactionAsync(token);try{await using(var d=c.CreateCommand()){d.Transaction=(Microsoft.Data.Sqlite.SqliteTransaction)tx;d.CommandText="DELETE FROM performance_rollups WHERE metric_kind=$kind AND resolution=$resolution AND period_start_utc>=$from";d.Parameters.AddWithValue("$kind",kind.ToString());d.Parameters.AddWithValue("$resolution",(int)resolution);d.Parameters.AddWithValue("$from",fromUtc.ToUniversalTime().ToString("O"));await d.ExecuteNonQueryAsync(token);}foreach(var x in rollups){await using var q=c.CreateCommand();q.Transaction=(Microsoft.Data.Sqlite.SqliteTransaction)tx;q.CommandText="INSERT INTO performance_rollups(id,metric_kind,resolution,period_start_utc,period_end_utc,minimum,maximum,average,p95,sample_count,coverage,unit,quality,aggregation_version)VALUES($id,$kind,$resolution,$start,$end,$min,$max,$avg,$p95,$count,$coverage,$unit,$quality,$version)";q.Parameters.AddWithValue("$id",x.Id.ToString());q.Parameters.AddWithValue("$kind",x.Kind.ToString());q.Parameters.AddWithValue("$resolution",(int)x.Resolution);q.Parameters.AddWithValue("$start",x.PeriodStartUtc.ToString("O"));q.Parameters.AddWithValue("$end",x.PeriodEndUtc.ToString("O"));q.Parameters.AddWithValue("$min",Db(x.Minimum));q.Parameters.AddWithValue("$max",Db(x.Maximum));q.Parameters.AddWithValue("$avg",Db(x.Average));q.Parameters.AddWithValue("$p95",Db(x.Percentile95));q.Parameters.AddWithValue("$count",x.SampleCount);q.Parameters.AddWithValue("$coverage",x.CoveragePercent);q.Parameters.AddWithValue("$unit",x.Unit);q.Parameters.AddWithValue("$quality",(int)x.Quality);q.Parameters.AddWithValue("$version",x.AggregationVersion);await q.ExecuteNonQueryAsync(token);}await tx.CommitAsync(token);Interlocked.Increment(ref _generation);}catch{await tx.RollbackAsync(CancellationToken.None);throw;}}
 public async Task<IReadOnlyList<PerformanceMetricSample>>ReadSamplesAsync(PerformanceMetricKind kind,DateTimeOffset fromUtc,DateTimeOffset toUtc,CancellationToken token){var items=new List<PerformanceMetricSample>();await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT id,captured_utc,value,unit,quality,source,detail FROM performance_samples WHERE metric_kind=$kind AND captured_utc BETWEEN $from AND $to ORDER BY captured_utc,id";Params(q,kind,fromUtc,toUtc);await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))items.Add(new(Guid.Parse(r.GetString(0)),kind,DateTimeOffset.Parse(r.GetString(1),CultureInfo.InvariantCulture),r.IsDBNull(2)?null:r.GetDouble(2),r.GetString(3),(MetricQuality)r.GetInt32(4),r.GetString(5),r.IsDBNull(6)?null:r.GetString(6)));return items;}
 public async Task<IReadOnlyList<PerformanceMetricRollup>>ReadRollupsAsync(PerformanceHistoryQuery x,CancellationToken token){var items=new List<PerformanceMetricRollup>();await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT id,period_start_utc,period_end_utc,minimum,maximum,average,p95,sample_count,coverage,unit,quality,aggregation_version FROM performance_rollups WHERE metric_kind=$kind AND resolution=$resolution AND period_start_utc BETWEEN $from AND $to ORDER BY period_start_utc,id";q.Parameters.AddWithValue("$kind",x.Kind.ToString());q.Parameters.AddWithValue("$resolution",(int)x.Resolution);q.Parameters.AddWithValue("$from",x.FromUtc.ToUniversalTime().ToString("O"));q.Parameters.AddWithValue("$to",x.ToUtc.ToUniversalTime().ToString("O"));await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))items.Add(new(Guid.Parse(r.GetString(0)),x.Kind,x.Resolution,DateTimeOffset.Parse(r.GetString(1)),DateTimeOffset.Parse(r.GetString(2)),N(r,3),N(r,4),N(r,5),N(r,6),r.GetInt32(7),r.GetDouble(8),r.GetString(9),(MetricQuality)r.GetInt32(10),r.GetString(11)));return items;}
 public async Task<PerformanceRetentionJob>ApplyRetentionAsync(DateTimeOffset raw,DateTimeOffset rollup,CancellationToken token){await using var c=database.OpenConnection();await using var tx=await c.BeginTransactionAsync(token);try{var ds=await Delete(c,(Microsoft.Data.Sqlite.SqliteTransaction)tx,"performance_samples","captured_utc",raw,token);var dr=await Delete(c,(Microsoft.Data.Sqlite.SqliteTransaction)tx,"performance_rollups","period_end_utc",rollup,token);var job=new PerformanceRetentionJob(Guid.NewGuid(),DateTimeOffset.UtcNow,raw,rollup,ds,dr,"performance-retention-v1");await using var q=c.CreateCommand();q.Transaction=(Microsoft.Data.Sqlite.SqliteTransaction)tx;q.CommandText="INSERT INTO performance_retention_jobs(id,executed_utc,raw_retain_after_utc,rollup_retain_after_utc,deleted_samples,deleted_rollups,policy_version)VALUES($id,$time,$raw,$rollup,$samples,$rollups,$version)";q.Parameters.AddWithValue("$id",job.Id.ToString());q.Parameters.AddWithValue("$time",job.ExecutedAtUtc.ToString("O"));q.Parameters.AddWithValue("$raw",raw.ToString("O"));q.Parameters.AddWithValue("$rollup",rollup.ToString("O"));q.Parameters.AddWithValue("$samples",ds);q.Parameters.AddWithValue("$rollups",dr);q.Parameters.AddWithValue("$version",job.PolicyVersion);await q.ExecuteNonQueryAsync(token);await tx.CommitAsync(token);Interlocked.Increment(ref _generation);return job;}catch{await tx.RollbackAsync(CancellationToken.None);throw;}}
 private static object Db(double?v)=>v is null?DBNull.Value:v.Value;private static double?N(Microsoft.Data.Sqlite.SqliteDataReader r,int i)=>r.IsDBNull(i)?null:r.GetDouble(i);private static void Params(Microsoft.Data.Sqlite.SqliteCommand q,PerformanceMetricKind k,DateTimeOffset f,DateTimeOffset t){q.Parameters.AddWithValue("$kind",k.ToString());q.Parameters.AddWithValue("$from",f.ToUniversalTime().ToString("O"));q.Parameters.AddWithValue("$to",t.ToUniversalTime().ToString("O"));}private static async Task<int>Delete(Microsoft.Data.Sqlite.SqliteConnection c,Microsoft.Data.Sqlite.SqliteTransaction tx,string table,string column,DateTimeOffset before,CancellationToken token){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText=$"DELETE FROM {table} WHERE {column}<$before";q.Parameters.AddWithValue("$before",before.ToUniversalTime().ToString("O"));return await q.ExecuteNonQueryAsync(token);}}
